from typing import Union, Optional

from taf.vran.vdu.enb.rest.provider import ReleaseProvider


class LTEvDUConnection:

    def __init__(
        self,
        host: str,
        port: str = "443",
        username: str = "Nemuadmin",
        password: str = "Nokia@123",
        release: Optional[str] = None,
        secure: bool = True,
        connection_name: str = "default",
        timeout: Union[int, float] = 30,
        read_only: bool = False,
        update_expired_password: bool = True
    ) -> None:
        """
        Sets up connection to 4G vDU by sending login request.

        :param str host: 4G vDU IP address, either IPv4 or IPv6. For example: "192.168.255.129"
        :param str port: 4G vDU port number. For example: "443"
        :param str username: 4G vDU username. For example: "Nemuadmin"
        :param str password: 4G vDU password. For example: "Nokia@123"
        :param Optional[str] release: 4G vDU release. Available options: "25r3".
                                      Defaults to None - newest release.
        :param bool secure: If True, HTTPS connection is used. If False, HTTP connection is used. Defaults to True.
        :param str connection_name: Alias for the connection. Defaults to "default".
        :param Union[int, float] timeout: Timeout for the connection. Defaults to 30 seconds.
        :param bool read_only: If True, the connection is read-only. Defaults to False.
        :param bool update_expired_password: If True, the connection will update expired password automatically.
                                             Otherwise, the user shall use `update_expired_password` keyword to update it.
                                             Defaults to True.

        :raises ReleaseNotSupported: If the given release is not supported.
        """
        self._lte_vdu = ReleaseProvider.get_release(
            host=host,
            port=port,
            username=username,
            password=password,
            release=release,
            secure=secure,
            timeout=timeout,
            connection_name=connection_name,
            read_only=read_only,
            update_expired_password=update_expired_password
        )
        self._lte_vdu.login()

    def disconnect(self) -> None:
        """
        Disconnects from the 4G vDU by sending logout request.
        """
        self._lte_vdu.logout()

    def perform_commissioning(
        self,
        scf_file: str,
        timeout: int = 300,
    ) -> dict:
        """
        Perform Commissioning - adds plan to staging, validates and activates it.

        :param str scf_file: Path to the SCF file with xml extension, for example: "/home/Desktop/vdu_scf.xml"
        :param Union[str, int, float] timeout: Timeout for the operation. Defaults to 300 seconds.

        :raises TimeoutError: If operation does not finish within the given timeout.
        :raises RuntimeError: If operation fails.
        :raises PlanValidationError: If plan validation fails.

        :returns: Response from the perform commissioning operation, for example:

            .. code-block:: python

                {
                   "basicReport":{
                      "activationErrors":[],
                      "commissioningType":"Full commissioning",
                      "dateAndTime":"2025-03-24T12:06:11+00:00",
                      "planActivationResult":"success",
                      "planValidationResult":"success",
                      "validationErrors":[]
                   },
                   "cmPlanId":"plan_20250324120610_43b9c171-9a58-4fa4-a714-343a9f57f80c",
                   "consistencyReport": [],
                   "id":"o_67d68b37-f63b-473f-95f6-d2174d06fc1e",
                   "procedureState":"planActivate",
                   "status":"success"
                }
        :rtype: dict
        """
        return self._lte_vdu.perform_commissioning(scf_file=scf_file, timeout=timeout)

