    def reset_vdu(
        self,
        graceful_cell_shutdown: bool = False,
        wait_for_completion: bool = True,
        timeout: int = 120
    ) -> dict:
        """
        Reset the 4G vDU.

        .. note::
            API endpoints used:
            1. vDU reset trigger: POST /api/cp-config/v1/vdu/operations/resets
            2. vDU reset operation status check: GET /api/cp-config/v1/vdu/operations/resets/{operationId}

        :param bool graceful_cell_shutdown: If True, the cells will be gracefully deactivated.
        :param bool wait_for_completion: If True, the function will wait for the reset to complete.
                                         If False, the function will return immediately after sending the trigger request.
                                         In such case get_reset_vdu_operation_status keyword can be used to check status.
                                         Defaults to True.
        :param int timeout: timeout for the reset operation to complete. Defaults to 120s

        :returns: operation info, for example:

        .. code-block:: python

            {
              "id": 101,
              "links": [
                {
                  "rel": "self",
                  "href": "/some/useful/links"
                }
              ],
              "status": "ongoing",
              "detailedStatuses": [
                {
                  "id": "1",
                  "status": "failed",
                  "errorText": "reset is already progressing"
                },
                {
                  "id": "2",
                  "status": "success"
                }
              ],
              "errorMessage": "error message",
              "errorCode": {
                "code": "user_restricted"
              }
            }
        :rtype: dict
        """
        return self._lte_vdu.reset_vdu(
            graceful_cell_shutdown=graceful_cell_shutdown,
            wait_for_completion=wait_for_completion,
            timeout=timeout
        )

    def get_reset_vdu_operation_status(self, operation_id: str) -> dict:
        """
        Get status of reset vDU operation triggered by reset_vdu keyword.

        :param operation_id: ID of reset vDU operation, can be taken from field "id" of reset_vdu output

        :returns: operation info, for example:

        .. code-block:: python

            {
              "id": 101,
              "links": [
                {
                  "rel": "self",
                  "href": "/some/useful/links"
                }
              ],
              "status": "ongoing",
              "detailedStatuses": [
                {
                  "id": "1",
                  "status": "failed",
                  "errorText": "reset is already progressing"
                },
                {
                  "id": "2",
                  "status": "success"
                }
              ],
              "errorMessage": "error message",
              "errorCode": {
                "code": "user_restricted"
              }
            }
        :rtype: dict
        """
        return self._lte_vdu.get_reset_vdu_operation_status(operation_id=operation_id)

    def update_expired_password(
        self,
        new_password: str,
        account_name: str = "Nemuadmin",
    ) -> dict:
        """
        Update expired password for the vDU.

        :param new_password: New password to set.
        :param account_name: Account name for which the password should be updated. Defaults to "Nemuadmin".

        :returns: Response of the update expired password request, for example:

            .. code-block:: python

                {
                  "summary": "Update local user account",
                  "content": "Success"
                }
        :rtype: dict
        """
        return self._lte_vdu.update_expired_password(new_password=new_password, account_name=account_name)

    def get_managed_objects(
        self,
        class_name: str,
        timeout: int = 30,
    ) -> list:
        """
        Get managed objects with parameters.

        :param str class_name: Class name for object matching filtering.
        :param int timeout: Timeout for the operation. Defaults to 30s.

        :returns: List with managed objects and their parameters, for example:

            .. code-block:: python

                [
                  {
                    "className": "NTP",
                    "distName": "MRBTS-100/MNL-1/MNLENT-1/SYNC-1/CLOCK-1/NTP-1",
                    "version": "TNL5G19_1901_010",
                    "payload": "{\"ntpAlarmingThreshold\": 180, \"ntpServerIpAddrList\":[\"10.192.33.0\",\"10.192.33.1\"]}"
                  }
                ]
        :rtype: list
        """
        return self._lte_vdu.get_managed_objects(class_name=class_name, timeout=timeout)

    def check_secret_mode(
        self,
        timeout: Union[str, int, float] = 30
    ) -> bool:
        """
        Check secret mode status

        :param Union[int, str, float] timeout: (optional) Timeout for the operation in seconds, defaults to 30
        :param Union[None, str, LTEvDUConnection] connection: Connection to the 4G vDU.
                                                              Defaults to the default connection.

        :returns: secret mode status
        :rtype: bool
        """
        return self._lte_vdu.check_secret_mode(timeout=timeout)
